import{_ as t,o,c as a,ae as n}from"./chunks/framework.Czhw_PXq.js";const g=JSON.parse('{"title":"ADR 014: Cloud Authentication Strategy (Google OAuth)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/014-cloud-authentication.md","filePath":"adr/014-cloud-authentication.md"}'),i={name:"adr/014-cloud-authentication.md"};function s(r,e,c,l,d,u){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-014-cloud-authentication-strategy-google-oauth" tabindex="-1">ADR 014: Cloud Authentication Strategy (Google OAuth) <a class="header-anchor" href="#adr-014-cloud-authentication-strategy-google-oauth" aria-label="Permalink to &quot;ADR 014: Cloud Authentication Strategy (Google OAuth)&quot;">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Accepted Date: 2026-03-04</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>As the application moves towards cloud deployment (Phase 4) and targets enterprise/public sector users, we need a robust, secure, and user-friendly authentication mechanism. The previous custom JWT implementation was sufficient for local dev but lacked features like &quot;Forgot Password&quot; (securely) and single-sign-on (SSO).</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>We decided to integrate <strong>Google Sign-In</strong> (OIDC) alongside the custom JWT auth, adhering to the standard hybrid verification flow.</p><ol><li><strong>Frontend</strong>: Use <code>@react-oauth/google</code> to obtain an <code>access_token</code> (Implicit/Token flow).</li><li><strong>Backend</strong>: Verify the token using Google&#39;s UserInfo API (<code>https://www.googleapis.com/oauth2/v3/userinfo</code>) instead of a heavy library, keeping dependencies minimal.</li><li><strong>Account Linking</strong>: Accounts are linked by email. If a user signs in with Google and an account acts with that email, they are logged in. If not, a new account is provisioned automatically with a random password hash.</li></ol><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li><strong>Security</strong>: Relies on Google&#39;s security for initial authentication. Backend still issues its own JWT for session management.</li><li><strong>UX</strong>: One-click login.</li><li><strong>Privacy</strong>: We only request <code>email</code> and <code>profile</code> scopes.</li><li><strong>Mocking</strong>: &quot;Forgot Password&quot; is implemented as a mock (logging token to console) for the TFM MVP to avoid SMTP complexity.</li></ul>',10)])])}const m=t(i,[["render",s]]);export{g as __pageData,m as default};
